<?php
namespace Nakhostin\PerformanceEngine\CSS;
final class UnusedCSSPolicy { public const REQUIRED = 'required'; public const DYNAMIC_REQUIRED = 'dynamic_required'; public const POSSIBLY_UNUSED = 'possibly_unused'; public const SAFE_TO_REMOVE = 'safe_to_remove'; public const UNKNOWN = 'unknown'; public function classify( string $selector, array $used, array $javascript_references = array() ): string { if ( '' === trim( $selector ) ) { return self::UNKNOWN; } if ( in_array( $selector, $used, true ) ) { return self::REQUIRED; } if ( preg_match( '/:(?:hover|focus|focus-visible|active|checked|disabled)|::(?:before|after)|\.(?:active|open|opened|selected|loading)(?:\b|[-_])|\.(?:is|has|woocommerce|elementor|wd)-/i', $selector ) ) { return self::DYNAMIC_REQUIRED; } foreach ( $javascript_references as $reference ) { if ( '' !== $reference && false !== strpos( $selector, (string) $reference ) ) { return self::DYNAMIC_REQUIRED; } } return self::POSSIBLY_UNUSED; } }
